<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import {workbenchRequest} from '../lib/backends'
import {formDraftKey,readFormDraft,writeFormDraft,clearFormDraft,copyForm,sameForm} from '../lib/formDrafts'
const props=defineProps({settings:Object,members:Array,documents:Array}),emit=defineEmits(['openConversation','changed'])
const gaps=ref([]),active=ref(null),busy=ref(false),error=ref(''),notice=ref(''),showDone=ref(false),target=ref(''),errorBox=ref(null)
const documentOptions=ref([]),documentsLoading=ref(false);let policyGeneration=0
const edit=ref({owner:'待分派',status:'open',note:'',document_id:'',question:''})
const labels={open:'待补齐',pending:'维护中',resolved:'已关联生效知识',withdrawn:'已撤销',merged:'已合并'}
const shown=computed(()=>gaps.value.filter(g=>showDone.value||['open','pending'].includes(g.status)))
const mergeTargets=computed(()=>gaps.value.filter(g=>g.id!==active.value?.id&&!['withdrawn','merged'].includes(g.status)))
const api=(p,m='GET',b)=>workbenchRequest(props.settings,p,m,b)
watch(()=>active.value?.id,async id=>{const n=++policyGeneration;documentOptions.value=[];if(!id)return;documentsLoading.value=true;try{const options=await api('/knowledge/gaps/'+id+'/documents?user_id='+encodeURIComponent(props.settings.userId));if(n!==policyGeneration)return;documentOptions.value=options;if(edit.value.document_id&&!options.some(d=>d.id===edit.value.document_id)){edit.value.document_id='';notice.value='原关联文档不再适用，请重新选择当前事项可用的规则'}}catch(e){if(n===policyGeneration)error.value=e.message}finally{if(n===policyGeneration)documentsLoading.value=false}})
const draftConflict=ref(false),draftBase=ref(1);let hydrating=true,initialEdit={}
const selectionKey=()=>formDraftKey(props.settings,'gap-selection','current'),gapKey=id=>formDraftKey(props.settings,'gap',id)
watch(edit,()=>{if(hydrating||!active.value)return;const key=gapKey(active.value.id);if(sameForm(edit.value,initialEdit))clearFormDraft(key);else writeFormDraft(key,{fields:copyForm(edit.value),base:draftBase.value})},{deep:true,flush:'sync'})
function rebase(){draftBase.value=active.value.revision||1;draftConflict.value=false;writeFormDraft(gapKey(active.value.id),{fields:copyForm(edit.value),base:draftBase.value})}
function discard(){clearFormDraft(gapKey(active.value.id));select(active.value)}
let generation=0
async function load(){const n=++generation;try{const data=await api('/knowledge/gaps?user_id='+encodeURIComponent(props.settings.userId));if(n===generation){gaps.value=data;const selected=active.value?.id||readFormDraft(selectionKey())?.id;const current=data.find(g=>g.id===selected);if(current)select(current)}}catch(e){if(n===generation)error.value=e.message}}
watch(()=>[props.settings.userId,props.settings.workspaceId],()=>{active.value=null;gaps.value=[];error.value='';notice.value='';load()},{immediate:true})
function select(g){if(!g){error.value='目标已变化，请刷新缺口';return}hydrating=true;active.value=g;edit.value={owner:g.owner,status:g.status,note:'',document_id:g.document_id||'',question:g.question};initialEdit=copyForm(edit.value);draftBase.value=g.revision||1;const saved=readFormDraft(gapKey(g.id));if(saved){edit.value={...edit.value,...saved.fields};draftBase.value=saved.base;showDone.value=true}draftConflict.value=!!saved&&saved.base!==(g.revision||1);hydrating=false;writeFormDraft(selectionKey(),{id:g.id});target.value='';error.value='';notice.value=''}
async function run(fn,message){if(busy.value)return;const key=props.settings.userId+':'+props.settings.workspaceId;busy.value=true;error.value='';try{await fn();if(key!==props.settings.userId+':'+props.settings.workspaceId)return;if(active.value)clearFormDraft(gapKey(active.value.id));clearFormDraft(selectionKey());active.value=null;await load();notice.value=message;emit('changed')}catch(e){if(key===props.settings.userId+':'+props.settings.workspaceId){error.value=e.message;await nextTick();errorBox.value?.focus()}}finally{busy.value=false}}
function save(){return run(()=>api('/knowledge/gaps/'+active.value.id,'PATCH',{user_id:props.settings.userId,...edit.value,document_id:edit.value.document_id||null,expected_revision:draftBase.value}),'缺口已更新，原问题与历史保留；客户事项不会自动结案')}
function merge(){const destination=mergeTargets.value.find(g=>g.id===target.value);if(!destination)return;return run(()=>api('/knowledge/gaps/'+active.value.id+'/merge','POST',{user_id:props.settings.userId,target_id:destination.id,expected_revision:draftBase.value,target_revision:destination.revision||1,note:edit.value.note}),'已合并缺口，原记录保留转向，来源事项归入目标；客户跟进不变')}
</script>
<template>
<section :aria-busy="busy" class="knowledge-gaps"><header><div><h2>待补齐的业务知识</h2><p class="source-note">关联生效业务文档后生成事项回查；误登记可更正、撤销或合并，并保留原因。</p></div><div class="actions"><label class="inline-check"><input type="checkbox" v-model="showDone"/>显示已完成、撤销与合并</label><button class="text-button" :disabled="busy" @click="load">刷新缺口</button></div></header><p v-if="error" ref="errorBox" tabindex="-1" class="form-error" role="alert">{{error}}</p><p v-if="notice" role="status" class="source-note">{{notice}}</p><div v-if="!shown.length" class="gap-empty">暂无待补齐知识。遇到缺少政策依据的问题时，在会话右侧登记知识缺口。</div><div v-else class="gap-layout"><div class="gap-list"><button v-for="g in shown" :key="g.id" :class="{selected:active?.id===g.id}" :disabled="busy" @click="select(g)"><strong>{{g.question}}</strong><span>{{labels[g.status]}} · {{g.owner}}</span></button></div><form v-if="active" @submit.prevent="save"><p class="form-draft-note">未提交的缺口说明会在当前用户和工作范围中保留。</p><div v-if="draftConflict" class="draft-conflict" role="alert"><strong>缺口已更新，旧草稿保留，尚未覆盖新记录。</strong><p>当前问题：{{active.question}}</p><button type="button" class="secondary" @click="rebase">已核对当前缺口，保留草稿继续编辑</button><button type="button" class="text-button" @click="discard">放弃此缺口草稿</button></div><p class="source-note">{{labels[active.status]}} · 版本 {{active.revision||1}}</p><label>缺口问题<textarea v-model.trim="edit.question" :readonly="active.status==='merged'" required maxlength="4000" rows="2"/></label><details><summary>原始问题与来源事项</summary><p>{{active.original_question||active.question}}</p><button v-for="id in active.source_conv_ids||[active.conv_id]" :key="id" class="text-button" type="button" :disabled="busy" @click="emit('openConversation',id)">打开来源事项 {{id.slice(0,8)}}</button></details><button v-if="active.merged_into" class="text-button" type="button" @click="select(gaps.find(g=>g.id===active.merged_into))">查看合并目标 →</button><template v-if="active.status!=='merged'"><div class="form-row"><label>维护负责人<select aria-label="维护负责人" v-if="settings.workspaceId" v-model="edit.owner"><option value="待分派">待分派</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option></select><input v-else v-model="edit.owner" maxlength="200" required/></label><label>缺口状态<select aria-label="缺口状态" v-model="edit.status"><option value="open">待补齐</option><option value="pending">维护中</option><option value="resolved">已补齐</option><option value="withdrawn">撤销误登记</option></select></label></div><label>对应生效文档<select aria-label="对应生效文档" :disabled="documentsLoading" v-model="edit.document_id" :required="edit.status==='resolved'"><option value="">{{documentsLoading?'正在核对适用文档…':'请选择当前事项适用的生效文档'}}</option><option v-for="d in documentOptions" :key="d.id" :value="d.id">{{d.title}} · 生效 v{{d.published_version}}</option></select></label><label>更正 / 处理 / 撤销原因<textarea v-model.trim="edit.note" required maxlength="2000" rows="2"/></label><button class="secondary" :disabled="busy||documentsLoading||draftConflict||!edit.note||!edit.question">保存缺口进展</button><details v-if="active.status!=='withdrawn'"><summary>合并到另一条有效缺口</summary><p class="source-note">保留原问题、来源事项与转向关系；不会自动结案。</p><label>合并目标<select aria-label="合并目标" v-model="target"><option value="">选择有效目标</option><option v-for="g in mergeTargets" :key="g.id" :value="g.id">{{g.question}}</option></select></label><button type="button" class="secondary" :disabled="busy||draftConflict||!target||!edit.note" @click="merge">按上述原因合并缺口</button></details></template><details v-if="active.history?.length"><summary>维护记录</summary><article v-for="(h,i) in active.history" :key="i"><p>{{h.actor}}：{{h.note}}</p><small v-if="h.previous?.question">修改前：{{h.previous.question}}</small></article></details></form><p v-else class="source-note">选择缺口后填写负责人、进展、原题更正或关联生效文档。</p></div></section>
</template>
